// Or groups predicates with the OR operator between them.
func Or(predicates ...predicate.AdminKey) predicate.AdminKey {
	return predicate.AdminKey(sql.OrPredicates(predicates...))
}

// Not applies the not operator on the given predicate.
func Not(p predicate.AdminKey) predicate.AdminKey {
	return predicate.AdminKey(sql.NotPredicates(p))
}
